mapper.sql:
select
from `resource` bres inner join role_resource brr on bres.id = brr.resource_id and brr.deleted = 0 inner join `role` br on brr.role_id = br.id and br.deleted = 0 and br.status = 1 inner join `org` bo on br.org_id = bo.id and bo.deleted = 0 and bo.status = 1 and bo.audit_status = 2 inner join user_role bur on br.id = bur.role_id and bur.deleted = 0 inner join `user` bu on bur.user_id = bu.id and bu.deleted = 0 and bu.enabled = 1 and bu.locked = 0 and bu.account_expired = 0 and bu.credentials_expired = 0 where bres.deleted = 0 and bres.status = 1 and bo.id = #{orgId} and bu.id = #{userId}
order by bres.seq asc

select
from `resource` bres inner join role_resource brr on bres.id = brr.resource_id and brr.deleted = 0 inner join `role` br on brr.role_id = br.id and br.deleted = 0 and br.status = 1 inner join `org` bo on br.org_id = bo.id and bo.deleted = 0 and bo.status = 1 and bo.audit_status = 2 inner join user_group_role bugr on br.id = bugr.role_id and bugr.deleted = 0 inner join user_group bug on bugr.user_group_id = bug.id and bug.deleted = 0 and bug.status = 1 inner join user_group_user bugu on bug.id = bugu.user_group_id and bugu.deleted = 0 inner join `user` bu on bugu.user_id = bu.id and bu.deleted = 0 and bu.enabled = 1 and bu.locked = 0 and bu.account_expired = 0 and bu.credentials_expired = 0 where bres.deleted = 0 and bres.status = 1 and bo.id = #{orgId} and bu.id = #{userId}
order by bres.seq asc

mapper.select:
select
,
from `resource` bres inner join `menu` bm on bres.menu_id = bm.id and bm.deleted = 0 and bm.status = 1 where bres.deleted = 0 and bres.id = #{id}
